#![allow(clippy::unwrap_used)]
use std::fs;
use std::io::Cursor;
use std::cell::RefCell;
use std::collections::BTreeMap;
use serde_json::{json, Value};
use ulw_loop_core::codex_hook::PreToolUsePayload;
use ulw_loop_core::spawn_guard::{apply_spawn_budget_guards_with_env, run_spawn_admission_recorder_cli_with_env};

thread_local! { static TEST_ENV: RefCell<BTreeMap<String, String>> = const { RefCell::new(BTreeMap::new()) }; }
fn set_env(key: &str, value: impl ToString) { TEST_ENV.with(|env| { env.borrow_mut().insert(key.into(), value.to_string()); }); }
fn remove_env(key: &str) { TEST_ENV.with(|env| { env.borrow_mut().remove(key); }); }
fn env(key: &str) -> Option<String> { TEST_ENV.with(|env| env.borrow().get(key).cloned()) }
fn setup() -> tempfile::TempDir { let d=tempfile::tempdir().unwrap(); set_env("PLUGIN_DATA",d.path().join("plugin-data").display()); remove_env("OMO_SPAWN_FANOUT_LIMIT"); remove_env("OMO_ULW_LOOP_REVIEW_SPAWN_LIMIT"); remove_env("OMO_AGENT_TOOLKIT_SURFACE"); d }
fn payload(d:&tempfile::TempDir, tool:&str, input:Value)->PreToolUsePayload { PreToolUsePayload{cwd:d.path().display().to_string(),hook_event_name:"PreToolUse".into(),model:"gpt-5.6-sol".into(),permission_mode:"default".into(),session_id:"s1".into(),tool_input:input,tool_name:tool.into(),tool_use_id:"tu1".into(),transcript_path:None,turn_id:"t1".into()} }
fn goals(d:&tempfile::TempDir, v2:bool) { let dir=d.path().join(".omo/ulw-loop/s1"); fs::create_dir_all(&dir).unwrap(); fs::write(dir.join("goals.json"),json!({"version":1,"createdAt":"2026-07-11T00:00:00.000Z","updatedAt":"2026-07-11T00:00:00.000Z","briefPath":".omo/ulw-loop/s1/brief.md","goalsPath":".omo/ulw-loop/s1/goals.json","ledgerPath":".omo/ulw-loop/s1/ledger.jsonl","codexGoalMode":"aggregate","evidenceLayoutVersion":if v2 {2} else {1},"goals":[{"id":"g1","title":"Final goal","objective":"Final goal","status":"in_progress","successCriteria":[{"id":"C001","scenario":"scenario","userModel":"happy","expectedEvidence":"evidence","capturedEvidence":"captured","status":"pass","capturedAt":"2026-07-11T00:00:00.000Z"},{"id":"C002","scenario":"scenario","userModel":"happy","expectedEvidence":"evidence","capturedEvidence":"captured","status":"pass","capturedAt":"2026-07-11T00:00:00.000Z"}],"attempt":1,"createdAt":"2026-07-11T00:00:00.000Z","updatedAt":"2026-07-11T00:00:00.000Z"}],"activeGoalId":"g1"}).to_string()).unwrap(); }
fn deny(s:&str)->Value{serde_json::from_str(s).unwrap()}
fn reason(s:&str)->String{deny(s)["hookSpecificOutput"]["permissionDecisionReason"].as_str().unwrap().into()}
fn guard(d:&tempfile::TempDir, input:Value)->String{apply_spawn_budget_guards_with_env(&payload(d,"spawn_agent",input),None,env)}
fn count(d:&tempfile::TempDir)->u64{serde_json::from_str::<Value>(&fs::read_to_string(d.path().join(".omo/ulw-loop/s1/spawn-count.json")).unwrap()).unwrap()["count"].as_u64().unwrap()}

#[test] fn records_each_breaker_reason_and_isolates_sessions(){for r in ["too many active cells","AgentLimitReached","max_threads","max_concurrent_threads_per_session"]{let d=setup();let mut out=Vec::new();run_spawn_admission_recorder_cli_with_env(Cursor::new(json!({"session_id":"s1","tool_response":r}).to_string()),&mut out,env);assert!(out.is_empty());let m:Value=serde_json::from_str(&fs::read_to_string(d.path().join("plugin-data/spawn-breaker/s1.json")).unwrap()).unwrap();assert_eq!(m["reason"],r);assert!(m["at"].as_str().unwrap().contains('T'));assert!(!guard(&d,json!({})).is_empty());}}
#[test] fn successful_admission_is_not_recorded(){let d=setup();let mut out=Vec::new();run_spawn_admission_recorder_cli_with_env(Cursor::new(r#"{"session_id":"s1","tool_response":{"agent_id":"worker-1"}}"#),&mut out,env);assert!(out.is_empty());assert!(!d.path().join("plugin-data/spawn-breaker/s1.json").exists());}
#[test] fn breaker_denies_before_other_guards(){let d=setup();goals(&d,false);fs::write(d.path().join(".omo/ulw-loop/s1/.state.lock"),r#"{"pid":1}"#).unwrap();let mut out=Vec::new();run_spawn_admission_recorder_cli_with_env(Cursor::new(r#"{"session_id":"s1","tool_response":"AgentLimitReached"}"#),&mut out,env);let s=guard(&d,json!({"agent_type":"lazycodex-gate-reviewer"}));assert!(reason(&s).contains("AgentLimitReached"));assert!(!d.path().join(".omo/ulw-loop/s1/spawn-count.json").exists());}
#[test] fn default_fanout_limit_is_24(){assert_eq!(ulw_loop_core::spawn_guard::DEFAULT_FANOUT_LIMIT,24);}
#[test] fn under_fanout_limit_allows_and_counts(){let d=setup();goals(&d,false);assert_eq!(guard(&d,json!({"message":"scan"})),"");assert_eq!(count(&d),1);}
#[test] fn env_fanout_limit_denies_fourth(){let d=setup();goals(&d,false);set_env("OMO_SPAWN_FANOUT_LIMIT","3");for _ in 0..3{assert_eq!(guard(&d,json!({"message":"scan"})),"");}assert!(reason(&guard(&d,json!({"message":"scan"}))).contains("4/3"));}
#[test] fn missing_session_state_noops(){let d=setup();assert_eq!(guard(&d,json!({"message":"scan"})),"");}
#[test] fn non_spawn_tool_noops(){let d=setup();goals(&d,false);assert_eq!(apply_spawn_budget_guards_with_env(&payload(&d,"create_goal",json!({"objective":"x"})),None,env),"");}
#[test] fn dotted_spawn_tokens_count(){let d=setup();goals(&d,false);set_env("OMO_SPAWN_FANOUT_LIMIT","1");assert_eq!(apply_spawn_budget_guards_with_env(&payload(&d,"collaboration.spawn_agent",json!({"message":"scan"})),None,env),"");assert!(reason(&apply_spawn_budget_guards_with_env(&payload(&d,"collaborationspawn_agent",json!({"message":"scan"})),None,env)).contains("2/1"));}
#[test] fn exhausted_fanout_does_not_charge_reviewer(){let d=setup();goals(&d,false);set_env("OMO_SPAWN_FANOUT_LIMIT","3");for _ in 0..3{assert_eq!(guard(&d,json!({"message":"scan"})),"");}assert!(reason(&guard(&d,json!({"agent_type":"lazycodex-code-reviewer","message":"review"}))).contains("4/3"));set_env("OMO_SPAWN_FANOUT_LIMIT","10");assert_eq!(guard(&d,json!({"agent_type":"lazycodex-code-reviewer","message":"review"})),"");}
#[test] fn reviewer_repetition_cap_resets_by_attempt(){let d=setup();goals(&d,false);let i=json!({"agent_type":"lazycodex-code-reviewer","message":"review"});for _ in 0..3{assert_eq!(guard(&d,i.clone()),"");}assert!(reason(&guard(&d,i.clone())).contains("4/3"));let p=d.path().join(".omo/ulw-loop/s1/goals.json");let mut v:Value=serde_json::from_str(&fs::read_to_string(&p).unwrap()).unwrap();v["goals"][0]["attempt"]=json!(2);fs::write(p,v.to_string()).unwrap();assert_eq!(guard(&d,i),"");}
#[test] fn mixed_prompt_charges_selected_qa_role(){let d=setup();goals(&d,false);for _ in 0..3{assert_eq!(guard(&d,json!({"message":"Act as lazycodex-code-reviewer"})),"");}assert_eq!(guard(&d,json!({"message":"Act as lazycodex-qa-executor; verify lazycodex-code-reviewer"})),"");}
#[test] fn gate_missing_artifact_denies_without_quota(){let d=setup();goals(&d,false);let s=guard(&d,json!({"message":"Act as lazycodex-gate-reviewer"}));assert!(reason(&s).contains("g1-manual-qa.md"));assert!(!d.path().join(".omo/ulw-loop/s1/review-spawn-counts.json").exists());}
#[test] fn explicit_gate_agent_type_names_missing_path(){let d=setup();goals(&d,false);let s=guard(&d,json!({"agent_type":"lazycodex-gate-reviewer","message":"final"}));assert!(reason(&s).contains("missing"));}
#[test] fn senpi_gate_with_qa_artifact_allows(){let d=setup();set_env("OMO_AGENT_TOOLKIT_SURFACE","omo-senpi");goals(&d,false);fs::create_dir_all(d.path().join(".omo/evidence")).unwrap();fs::write(d.path().join(".omo/evidence/g1-manual-qa.md"),"matrix").unwrap();assert_eq!(guard(&d,json!({"agent_type":"omo-senpi-gate-reviewer","message":"audit"})),"");}
#[test] fn senpi_gate_without_qa_denies(){let d=setup();set_env("OMO_AGENT_TOOLKIT_SURFACE","omo-senpi");goals(&d,false);assert!(reason(&guard(&d,json!({"agent_type":"omo-senpi-gate-reviewer"}))).contains("g1-manual-qa.md"));}
#[test] fn senpi_gate_code_review_only_denies_qa(){let d=setup();set_env("OMO_AGENT_TOOLKIT_SURFACE","omo-senpi");goals(&d,false);fs::create_dir_all(d.path().join(".omo/evidence")).unwrap();fs::write(d.path().join(".omo/evidence/g1-code-review.md"),"report").unwrap();assert!(reason(&guard(&d,json!({"agent_type":"omo-senpi-gate-reviewer"}))).contains("g1-manual-qa.md"));}
#[test] fn generic_gate_message_denies(){let d=setup();goals(&d,false);assert!(deny(&guard(&d,json!({"message":"run FINAL GATE REVIEW"}))).is_object());}
#[test] fn senpi_gate_aliases_share_cap(){let d=setup();set_env("OMO_AGENT_TOOLKIT_SURFACE","omo-senpi");goals(&d,false);fs::create_dir_all(d.path().join(".omo/evidence")).unwrap();for n in ["g1-code-review.md","g1-manual-qa.md"]{fs::write(d.path().join(".omo/evidence").join(n),"x").unwrap();}let a=json!({"message":"run final gate review"});let b=json!({"message":"Act as omo-senpi-gate-reviewer"});for i in [a.clone(),b.clone(),a]{assert_eq!(guard(&d,i),"");}assert!(reason(&guard(&d,b)).contains("4/3"));}
#[test] fn senpi_code_review_aliases_share_cap(){let d=setup();set_env("OMO_AGENT_TOOLKIT_SURFACE","omo-senpi");goals(&d,false);let a=json!({"message":"Act as omo-senpi-code-reviewer"});let b=json!({"message":"Act as lazycodex-code-reviewer"});for i in [a.clone(),b.clone(),a]{assert_eq!(guard(&d,i),"");}assert!(reason(&guard(&d,b)).contains("4/3"));}
#[test] fn v1_manual_qa_artifact_allows_gate(){let d=setup();goals(&d,false);fs::create_dir_all(d.path().join(".omo/evidence")).unwrap();fs::write(d.path().join(".omo/evidence/g1-manual-qa.md"),"matrix").unwrap();assert_eq!(guard(&d,json!({"agent_type":"lazycodex-gate-reviewer"})),"");}
#[test] fn v2_flat_artifact_denies_attempt_path(){let d=setup();goals(&d,true);fs::create_dir_all(d.path().join(".omo/evidence")).unwrap();fs::write(d.path().join(".omo/evidence/g1-code-review.md"),"stale").unwrap();assert!(reason(&guard(&d,json!({"agent_type":"lazycodex-gate-reviewer"}))).contains(".omo/evidence/ulw/s1/g1/a1/g1-manual-qa.md"));}
#[test] fn v2_attempt_artifact_allows_gate(){let d=setup();goals(&d,true);let p=d.path().join(".omo/evidence/ulw/s1/g1/a1");fs::create_dir_all(&p).unwrap();fs::write(p.join("g1-manual-qa.md"),"matrix").unwrap();assert_eq!(guard(&d,json!({"agent_type":"lazycodex-gate-reviewer"})),"");}
#[test] fn incomplete_criteria_noop_gate(){let d=setup();goals(&d,false);let p=d.path().join(".omo/ulw-loop/s1/goals.json");let mut v:Value=serde_json::from_str(&fs::read_to_string(&p).unwrap()).unwrap();v["goals"][0]["successCriteria"][1]["status"]=json!("pending");fs::write(p,v.to_string()).unwrap();assert_eq!(guard(&d,json!({"agent_type":"lazycodex-gate-reviewer"})),"");}
#[test] fn non_gate_reviewer_ignores_artifacts(){let d=setup();goals(&d,false);assert_eq!(guard(&d,json!({"agent_type":"lazycodex-code-reviewer","message":"review"})),"");}
